def name_operands(region,address,operation):
 if region=='Station' and address==0x683A:
  operation=operation.replace('CALL #C85E','CALL @Station.CloseMenuOnRow.Entry').replace('LD HL, #9A58','LD HL, @Station.EmptyCallback.Entry').replace('(#9A89)','(@MenuCommandState.PeriodicCall)').replace('LD HL, #0020','LD HL, @D3DPreviewConst.ThirdStep').replace('LD HL, #FFE0','LD HL, @D3DPreviewConst.ThirdBackStep')
 return operation
